package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamPrepConjBank2 {
  private const val T = "Conjunctions & Sentence Connectors"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("He studied diligently for the exam, ___ he missed a few marks.", "yet", "so", "for", "therefore", "'Yet' (or 'but') links two contrasting clauses."),
    q("She stayed indoors all afternoon ___ it was pouring heavily.", "because", "although", "unless", "so", "'Because' introduces the reason for staying indoors."),
    q("It was raining heavily, ___ the inter-house match was postponed.", "so", "because", "although", "unless", "'So' introduces the result or consequence."),
    q("___ the heavy morning traffic, the school bus arrived on time.", "Despite", "Although", "Even though", "Because", "'Despite' precedes a noun phrase ('the heavy morning traffic') to show contrast."),
    q("___ it rained heavily, the scouts completed the hike cheerfully.", "Although", "Despite", "In spite of", "Because of", "'Although' precedes a full subject + verb clause ('it rained')."),
    q("In ___ of the steep climb, all the hikers reached the peak.", "spite", "despite", "although", "because", "Fixed phrase is 'In spite of' + noun phrase (never 'Despite of')."),
    q("___ facing numerous difficulties, the volunteers completed the hall.", "Despite", "Although", "Even though", "Since", "'Despite' can precede a gerund/V-ing phrase ('facing...')."),
    q("___ the poor weather, the cultural pageant attracted a huge crowd.", "In spite of", "Although", "Even though", "Because", "'In spite of + noun phrase' expresses contrast."),
    q("The cricket match was cancelled ___ of the flooded outfield.", "because", "despite", "although", "since", "'Because of + noun phrase' states the cause."),
    q("___ his sprained ankle, Kasun cheered loudly for his house.", "Despite", "Although", "Unless", "Because", "'Despite + noun phrase' expresses concession."),
    q("Neither Kamal ___ Nimal was absent from the extra English class.", "nor", "or", "and", "also", "Correlative conjunction pair: 'Neither ... nor'."),
    q("Either you finish the poster today ___ submit it Monday morning.", "or", "nor", "and", "but", "Correlative conjunction pair: 'Either ... or'."),
    q("Both the principal ___ the teachers praised the drama club.", "and", "or", "nor", "but", "Correlative conjunction pair: 'Both ... and'."),
    q("Not only did she win the essay prize ___ she also topped the quiz.", "but", "and", "yet", "so", "Correlative pair: 'Not only ... but also'."),
    q("Wait at the main gate ___ your elder brother arrives.", "until", "since", "because", "unless", "'Until' means up to the time when an event happens."),
    q("___ we stepped outside, a cool evening breeze greeted us.", "As soon as", "Unless", "Although", "In order to", "'As soon as' indicates immediate sequence in time."),
    q("Wash your hands neatly ___ sitting down for lunch.", "before", "unless", "although", "because", "'Before + V-ing' shows chronological order."),
    q("___ completing his homework, Ruwan helped clean the porch.", "After", "Unless", "Although", "Until", "'After + V-ing' indicates a subsequent action."),
    q("Read the passage twice ___ you understand every detail clearly.", "so that", "in order to", "although", "unless", "'So that + clause' expresses purpose."),
    q("She woke up at five ___ revise her science notes peacefully.", "in order to", "so that", "because of", "despite", "'In order to + base verb' expresses purpose."),
    q("Wear a hat ___ protect your head from the midday sun.", "to", "for", "so that", "because", "'To + base verb' (infinitive of purpose) pairs with 'protect'."),
    q("He spoke loudly ___ everyone at the back could hear him.", "so that", "in order to", "despite", "unless", "'So that + subject + could/can' states intended result."),
    q("You won't improve your writing ___ you practise regularly.", "unless", "if", "because", "since", "'Unless' means 'if not'."),
    q("Take a spare pen ___ your ink runs out during the exam.", "in case", "unless", "although", "therefore", "'In case' introduces preparation for a possibility."),
    q("The hall was ___ crowded that latecomers had to stand.", "so", "such", "too", "very", "'So + adjective + that' expresses degree and result."),
    q("It was ___ an inspiring speech that everyone applauded.", "such", "so", "too", "very", "'Such + a/an + adjective + noun + that' expresses result."),
    q("He walked slowly ___ he wouldn't wake the sleeping baby.", "lest", "unless", "although", "because", "'Lest' (for fear that) pairs with 'wouldn't/shouldn't/should'."),
    q("We can play badminton today, ___ go cycling tomorrow.", "or", "nor", "yet", "for", "'Or' presents an alternative choice."),
    q("She likes classical music, ___ her sister prefers modern pop.", "whereas", "because", "therefore", "unless", "'Whereas' highlights a direct contrast between two subjects."),
    q("The roads were slippery; ___, the driver reduced speed carefully.", "therefore", "however", "nevertheless", "meanwhile", "'Therefore' introduces a logical consequence after a semicolon."),
    q("The hike was exhausting; ___, everyone enjoyed the mountain view.", "nevertheless", "therefore", "consequently", "moreover", "'Nevertheless' (or 'however') introduces a contrast despite difficulty."),
    q("Reading expands vocabulary; ___, it strengthens writing style.", "moreover", "however", "otherwise", "instead", "'Moreover' adds a supporting point."),
    q("Start revising early; ___, you will feel stressed before exams.", "otherwise", "moreover", "therefore", "however", "'Otherwise' warns of the consequence of not doing something."),
    q("He didn't buy the expensive watch; ___, he bought useful books.", "instead", "moreover", "therefore", "although", "'Instead' indicates choosing an alternative."),
    q("Mother prepared evening tea; ___, Father watered the vegetable plot.", "meanwhile", "therefore", "otherwise", "unless", "'Meanwhile' links two simultaneous actions occurring at the same time."),
    q("___ it was getting dark, we hurried back to the main road.", "Since", "Although", "Unless", "Despite", "'Since' at the start can mean 'because'."),
    q("___ you have finished your essay, you may read a storybook.", "As", "Unless", "Although", "Despite", "'As' introduces a known reason ('since/because')."),
    q("The farmer worked hard in the field ___ sunrise to sunset.", "from", "since", "between", "until", "Fixed time span pair: 'from ... to'."),
    q("Whether we win ___ lose, we will play fairly and cheerfully.", "or", "nor", "and", "but", "Correlative pair: 'Whether ... or'."),
    q("The boy ran as fast as he could ___ he still missed the bus.", "but", "so", "because", "since", "'But' joins unexpected contrasting outcomes."),
    q("She can speak both Sinhala and Tamil, ___ she is learning French.", "and", "nor", "unless", "lest", "'And' adds parallel information."),
    q("I didn't go to the party, ___ did I receive an invitation.", "nor", "or", "but", "so", "'Nor + auxiliary + subject' follows a negative clause."),
    q("The tea was too hot to drink, ___ we waited five minutes.", "so", "for", "yet", "nor", "'So' expresses the logical result."),
    q("He wore a thick sweater, ___ the morning air was chilly.", "for", "so", "yet", "or", "'For' as a coordinating conjunction means 'because'."),
    q("___ being tiny, ants can carry items heavier than themselves.", "Despite", "Although", "Because", "Unless", "'Despite + V-ing (being)' expresses contrast."),
    q("___ he tried three times, he could not lift the iron box.", "Even though", "Despite", "In spite of", "Because of", "'Even though + subject + verb' emphasizes strong contrast."),
    q("___ the loud thunder, the little child slept peacefully.", "In spite of", "Even though", "Although", "Since", "'In spite of + noun phrase' expresses contrast."),
    q("___ of the heavy landslide, the Kandy road was closed briefly.", "Because", "Despite", "Although", "Instead", "'Because of + noun phrase' explains the cause."),
    q("The bridge was closed; ___, buses took a longer bypass route.", "consequently", "however", "nevertheless", "meanwhile", "'Consequently' introduces a direct result."),
    q("She missed two weeks of class; ___, she passed with high marks.", "however", "therefore", "consequently", "moreover", "'However' introduces a surprising contrast."),
    q("English is useful for higher studies; ___, it aids global travel.", "furthermore", "however", "otherwise", "nevertheless", "'Furthermore' adds another supporting point."),
    q("The library was quiet; ___, students could concentrate easily.", "thus", "however", "otherwise", "whereas", "'Thus' means 'as a result'."),
    q("You can pay for the ticket in cash ___ by bank card.", "or", "nor", "yet", "so", "'Or' offers an alternative method."),
    q("He was neither angry ___ disappointed by the delay.", "nor", "or", "and", "but", "'Neither' pairs strictly with 'nor'."),
    q("The hotel offers not only clean rooms ___ also scenic views.", "but", "and", "yet", "so", "'Not only ... but also' connects balanced structures."),
    q("No sooner had we entered the hall ___ the lights dimmed.", "than", "when", "then", "that", "'No sooner ... than' expresses immediate sequence."),
    q("Hardly had the rain stopped ___ a bright rainbow appeared.", "when", "than", "that", "then", "'Hardly ... when' marks an immediate following event."),
    q("Scarcely had he sat down ___ the telephone began to ring.", "when", "than", "as", "until", "'Scarcely ... when' marks immediate succession."),
    q("___ I was walking home, I met our former science teacher.", "While", "During", "Until", "Unless", "'While + clause' introduces an ongoing background action."),
    q("Stay inside the bus ___ the conductor gives the signal.", "until", "during", "while", "since", "'Until' specifies waiting up to a future event."),
    q("We haven't met our cousin ___ he moved to Trincomalee.", "since", "until", "during", "unless", "'Since + Simple Past' marks the starting point up to now."),
    q("Look both ways carefully ___ you cross the busy main street.", "before", "unless", "although", "since", "'Before' orders safety action prior to crossing."),
    q("She felt much more confident ___ she had revised every unit.", "after", "unless", "until", "before", "'After + Past Perfect' shows completed preparation first."),
    q("Keep this medicine in a cool place ___ it loses effectiveness.", "or else", "so that", "in case of", "provided", "'Or else' means 'otherwise'."),
    q("You may borrow my bicycle ___ you bring it back by six.", "on condition that", "even though", "in spite of", "nevertheless", "'On condition that' states an explicit agreement."),
    q("___ fast he ran, he couldn't catch the departing train.", "However", "Although", "Despite", "Because", "'However + adjective/adverb' means 'no matter how'."),
    q("Rich ___ he was, the merchant lived a very simple life.", "as", "despite", "unless", "because", "'Adjective + as + subject + verb' expresses concession ('Though he was rich')."),
    q("She speaks English clearly, ___ she writes even more fluently.", "and", "or", "nor", "unless", "'And' joins two positive complementary facts."),
    q("The team played bravely, ___ the opposing side was stronger.", "even though", "because", "therefore", "so that", "'Even though' contrasts brave effort against stronger opponents."),
    q("___ his illness, Kamal managed to sit all nine O/L papers.", "In spite of", "Although", "Even if", "Because", "'In spite of + noun phrase (his illness)' shows concession."),
    q("___ he was feeling unwell, Kamal sat all nine O/L papers.", "Although", "Despite", "In spite of", "Because of", "'Although + clause (he was feeling...)' shows concession."),
    q("The crop failed ___ the prolonged dry weather in July.", "due to", "although", "despite", "unless", "'Due to + noun phrase' states the reason."),
    q("___ the prolonged drought, farmers grew drought-resistant millet.", "Despite", "Due to", "Because of", "Since", "'Despite' contrasts action against unfavourable weather."),
    q("Finish your breakfast quickly ___ we won't be late for assembly.", "so that", "in order to", "despite", "although", "'So that + clause' expresses intended purpose."),
    q("We left home an hour early ___ miss the morning express train.", "so as not to", "so that not", "in order that", "despite not", "Negative infinitive of purpose uses 'so as not to + V1'."),
    q("He locked the storeroom door carefully ___ stray dogs entered.", "in case", "unless", "although", "moreover", "'In case' guards against a possible event."),
    q("The mountain path was narrow; ___, the guide led us safely.", "nonetheless", "therefore", "consequently", "moreover", "'Nonetheless' expresses contrast ('in spite of that')."),
    q("Solar panels cut power bills; ___, they reduce carbon emissions.", "additionally", "however", "otherwise", "nevertheless", "'Additionally' adds another positive benefit."),
    q("First, read the prompt carefully; ___, outline your main points.", "then", "however", "otherwise", "unless", "'Then' indicates the next logical step in a sequence."),
    q("___, let us thank the principal for organizing this workshop.", "Finally", "However", "Otherwise", "Instead", "'Finally' marks the concluding point in a sequence."),
    q("She looked worried, ___ she had not received the letter yet.", "for", "so", "yet", "or", "'For' introduces the explanation for her worried look."),
    q("Not only the library ___ also the hall is open on Saturdays.", "but", "and", "or", "nor", "'Not only A but also B' links two subjects."),
    q("Either the monitor ___ the vice-monitor collects the books.", "or", "nor", "and", "but", "'Either A or B' links two alternatives."),
    q("Neither the blue pen ___ the black one has any ink left.", "nor", "or", "and", "but", "'Neither A nor B' joins two negative subjects."),
    q("Both Colombo ___ Kandy have rich historical landmarks.", "and", "or", "nor", "but", "'Both A and B' joins two positive items."),
    q("I enjoy reading biographies ___ my brother prefers science fiction.", "while", "unless", "therefore", "because", "'While' expresses mild contrast between two preferences."),
    q("Wait here ___ I check whether the headmaster is free.", "while", "during", "despite", "since", "'While + clause' expresses an action happening at the same time."),
    q("___ entering the shrine room, remove your shoes neatly.", "Before", "Although", "Unless", "Because", "'Before + V-ing' indicates a required prior action."),
    q("___ finishing her degree, she joined a school in Kurunegala.", "After", "Although", "Unless", "Until", "'After + V-ing' shows what happened next."),
    q("He walked quietly ___ disturb the students writing the test.", "in order not to", "so that not", "although not to", "unless to", "Negative purpose before a verb uses 'in order not to'."),
    q("The parcel was well packed; ___, the glass jar inside stayed intact.", "consequently", "however", "otherwise", "meanwhile", "'Consequently' shows a direct positive result."),
    q("We wanted to visit Horton Plains; ___, dense fog blocked the road.", "unfortunately", "therefore", "moreover", "consequently", "'Unfortunately' introduces an adverse contrasting fact."),
    q("It looks like rain; ___, I think we should take umbrellas.", "therefore", "however", "although", "unless", "'Therefore' introduces a sensible conclusion."),
    q("___ you respect others, others will naturally respect you.", "If", "Unless", "Although", "Despite", "'If' states a positive condition leading to a result."),
    q("___ you leave the light on all night, the battery will drain.", "If", "Unless", "Although", "In spite of", "'If' introduces the cause of the battery draining."),
    q("She was tired, ___ she stayed up to complete her science project.", "yet", "so", "for", "therefore", "'Yet' highlights persistence despite tiredness."),
    q("Check every spelling carefully ___ handing in your paper.", "before", "unless", "although", "because", "'Before + V-ing' indicates timing before submission."),
    q("___ the bell had rung, the students stayed to ask one question.", "Even though", "Because", "Therefore", "Despite", "'Even though + clause' expresses surprising concession.")
  )
}
